#!/usr/bin/env bash
# Verifier driver for step 14 (quiche 0.26.0).
#
# Generated by misc/quic-http3-stack-multiversion/tools/gen-step.py from the
# shared frame plus this step's group list. Edit the frame or the step part and
# regenerate; do not edit one copy in isolation. After Phase 3 opens on a step
# the generated copy becomes authoritative and the reviser edits it directly —
# `tools/carryover-check.sh` is what keeps the fifteen copies honest after that.
set -u
source /tests/helpers.sh

# --- verifier/step binding check -------------------------------------------
# Must be the first thing that runs: /etc/harbor-step-id names the image, the
# literal below names this tests/ tree, and a disagreement means the build
# context was served from another step's cache entry.
require_step 14
# --- end binding check ------------------------------------------------------

# ---------------------------------------------------------------------------
# 0. Crash path.
#
# Under `multi_step_reward_strategy = "mean"` a verifier that exits without a
# reward.json costs the whole trial the steps after it, so every exit from here
# on writes a complete scorecard and exits 0. `fail_everything` is the
# scorecard for a driver that died before it could measure anything.
#
# It reports `gate: 0` with an empty `gate_failures`, and that pairing is the
# signal: a gate of zero with no group named is the driver failing, not a
# candidate regressing. Anything that vetoes a real step names the group and
# quotes what it saw.
# ---------------------------------------------------------------------------
reported=0

fail_everything() {
    local reason="$1"
    printf '{"step":%s,"reward":0.000000,"gate":0,"score":0.000000,"gate_failures":[],"candidate_build":0,"harness_build":0,"fixture_ok":0,"budget_exhausted":0,"crate_dir":"unresolved","build_note":"%s","gate_groups":{},"scored_groups":{}}\n' \
        "${step_num:-0}" "$reason" > /logs/verifier/reward_details.json
    printf '{"reward":0.000000}\n' > /logs/verifier/reward.json
}

on_exit() {
    local status=$?
    if [ "${reported:-0}" -ne 1 ]; then
        fail_everything "the verifier driver exited with status $status before it reported: nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    fi
    exit 0
}
trap on_exit EXIT

step_num=14
step_tag=0.26.0
log_dir=/tmp/quiche-verifier-14
harness=/tmp/quiche-harness-14
assets=/tests/assets
mkdir -p "$log_dir"

# ---------------------------------------------------------------------------
# 1. Fixture integrity.
#
# The verifier-owned corpus — the RFC 9001 Appendix A vectors, the frame and
# QPACK vector files, and the e2e drivers — is a prerequisite for the groups
# that consume it, never a score point of its own. A broken corpus fails those
# groups; it must not short-circuit the independent ones or erase earned
# credit.
# ---------------------------------------------------------------------------
expected_assets_sha=4d00dcc0b80c6009826e846a9f967b944f55e14b3bde3a5436f3c7cb783d68ac
expected_asset_files=47

actual_assets_sha=$(cd "$assets" && find . -type f -print0 | LC_ALL=C sort -z \
    | xargs -0 sha256sum | sha256sum | awk '{print $1}')
actual_asset_files=$(find "$assets" -type f | wc -l)

fixture_ok=1
[ "$actual_assets_sha" = "$expected_assets_sha" ] || fixture_ok=0
[ "$actual_asset_files" -eq "$expected_asset_files" ] || fixture_ok=0

# ---------------------------------------------------------------------------
# 2. Locating the candidate's transport crate.
#
# The library lives at the workspace root until milestone 6 and under
# `quiche/` from milestone 6 onward. Both layouts are accepted everywhere and
# the layout itself is scored by its own group at the step that introduces it,
# so a candidate that has not yet moved the tree loses that one group rather
# than every group in the step. TEST_INTERFACE.md states this probe.
# ---------------------------------------------------------------------------
crate_dir=unresolved
for cand in /app/quiche /app; do
    if [ -f "$cand/Cargo.toml" ] && grep -Eq '^[[:space:]]*name[[:space:]]*=[[:space:]]*"quiche"' "$cand/Cargo.toml"; then
        crate_dir=$cand
        break
    fi
done

workspace_root=/app
[ -f /app/Cargo.toml ] || workspace_root=$crate_dir

# ---------------------------------------------------------------------------
# 2. (continued) Which BoringSSL this tree was written against.
#
# The image pins the library this milestone's release pins, and the environment
# names it. At most steps that is the only copy and this loop does nothing.
#
# Where the QUIC callback struct changed shape across a step boundary, the
# image carries the previous release's pin as well. `SSL_QUIC_METHOD` is a
# struct of function pointers passed to `SSL_set_quic_method`: releases up to
# 0.1.0 declare four members, beginning `set_encryption_secrets`; from 0.3.0
# they declare five, beginning `set_read_secret` and `set_write_secret`. A tree
# of the older shape handed to a library of the newer one links cleanly -- the
# symbol exists and takes a pointer -- and then reads one member past the end
# of the struct, calling the wrong function for every callback. Nothing errors.
# The handshake simply never emits a ClientHello, and the step's inherited
# regression groups fail for a linkage reason wearing behaviour's clothes.
#
# So the shape is read out of the candidate's own `src/tls.rs` and the matching
# library selected. The test is deliberately two-sided -- the old name present
# AND the new names absent -- so a tree part-way through the conversion, or one
# that merely mentions the old name in a comment, keeps this release's library.
# The shape is read out of *live code*: `//` comments are stripped before the
# two greps run, so a migration note naming the old field cannot flip the pick.
# A candidate who does the work is unaffected: the environment already names
# the right one, and this loop never fires. It cannot manufacture a pass for
# the scored groups either; those ask for behaviour this milestone introduced,
# which no older library supplies.
#
# `.cargo/config.toml` in the workdir sets the same variable through cargo's
# `[env]` table, which without `force = true` yields to a variable already set
# in the environment -- so exporting here is enough, and the file stays honest
# about the default.
# ---------------------------------------------------------------------------
if [ -n "${QUICHE_BSSL_PATH:-}" ] && [ -f "$crate_dir/src/tls.rs" ] &&
    sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_encryption_secrets' &&
    ! sed 's,//.*,,' "$crate_dir/src/tls.rs" | grep -q 'set_read_secret'; then
    for alt in /opt/bssl/*; do
        [ -d "$alt" ] || continue
        [ "$alt" = "$QUICHE_BSSL_PATH" ] && continue
        QUICHE_BSSL_PATH=$alt
        export QUICHE_BSSL_PATH
        break
    done
fi

# ---------------------------------------------------------------------------
# 2a. The time budget, and why these numbers.
#
# `task.toml` gives this step `[steps.verifier] timeout_sec = 3600`. If the
# verifier is killed by that timeout it never writes reward.json and the run is
# unattributable rather than a zero, so the work inside must provably fit
# whatever the candidate does:
#
#   verify the pinned asset corpus                               <   5 s
#   CANDIDATE_BUILD_TIMEOUT  one `cargo build` of /app, cold    <= 1000 s
#   EXAMPLES_BUILD_TIMEOUT   the best-effort examples pass      <=  240 s
#   APPS_BUILD_TIMEOUT       the best-effort app-package pass   <=  240 s
#   HARNESS_BUILD_TIMEOUT    one `cargo test --no-run` of the
#                            verifier-owned harness crate       <=  800 s
#   CASE_BUDGET_TOTAL        every gate check and every scored
#                            group together                     <= 1200 s
#   write the two JSON files                                     <   5 s
#                                                    worst case   3490 s
#
# PER_CASE_MAX is far above any real case and far below the aggregate: one
# hanging case costs its own group and at most 120 s of the shared pool, so a
# step with many hanging cases degrades group by group instead of taking the
# run down. BoringSSL and the whole dependency graph are prebuilt into the
# image, so the candidate build is the candidate's own code and nothing else.
CANDIDATE_BUILD_TIMEOUT=1000
EXAMPLES_BUILD_TIMEOUT=240
APPS_BUILD_TIMEOUT=240
HARNESS_BUILD_TIMEOUT=800
CASE_BUDGET_TOTAL=1200
PER_CASE_MAX=120

# ---------------------------------------------------------------------------
# 3. Build the candidate workspace once, before anything is scored.
#
# Recorded separately from the groups: every group runs against this build, so
# one compile error would otherwise be reported as N unrelated capability gaps.
# ---------------------------------------------------------------------------
candidate_build=0
if [ "$crate_dir" != unresolved ]; then
    # Default targets only -- libraries and binaries. Deliberately not
    # `--all-targets`: that would also compile the candidate's own test and
    # bench targets, so a broken test of theirs would fail the build and be
    # reported as every capability missing at once. Their tests are not what
    # this verifier measures.
    (cd "$workspace_root" && timeout "$CANDIDATE_BUILD_TIMEOUT" \
        cargo build --offline -j 4) \
        >"$log_dir/candidate-build.log" 2>&1 && candidate_build=1
    # The client and server lived under examples/ before they became their own
    # package. Best-effort and never fatal: at releases where they are bins the
    # build above already produced them, and at releases where there are no
    # examples this is a no-op.
    if [ "$candidate_build" -eq 1 ]; then
        (cd "$workspace_root" && timeout "$EXAMPLES_BUILD_TIMEOUT" \
            cargo build --offline --examples -j 4) \
            >"$log_dir/candidate-examples.log" 2>&1 || true
    fi
    # Later they moved out of examples/ and into a package of their own --
    # `tools/apps` first, then `apps`. Where that package is a workspace member
    # the build above already covered it; where it exists but the root manifest
    # has no [workspace] section, cargo never descends into it, so the tree
    # ships the client and server sources and produces neither binary. Building
    # the package where it sits covers that window, and builds more of the
    # candidate rather than asking less of it.
    #
    # Best-effort, like the examples pass, and bounded as one pass rather than
    # one per path: at a release whose lockfile predates this package's own
    # dependencies it cannot resolve offline at all, which is a property of the
    # pinned corpus and not a candidate defect. Building a non-member package
    # makes cargo write a lockfile beside its manifest; no group reads one.
    if [ "$candidate_build" -eq 1 ]; then
        apps_deadline=$(( $(date +%s) + APPS_BUILD_TIMEOUT ))
        for app in tools/apps apps; do
            [ -f "$workspace_root/$app/Cargo.toml" ] || continue
            left=$(( apps_deadline - $(date +%s) ))
            [ "$left" -gt 0 ] || break
            (cd "$workspace_root/$app" && timeout "$left" \
                cargo build --offline -j 4) \
                >"$log_dir/candidate-app-$(printf '%s' "$app" | tr / -).log" \
                2>&1 || true
        done
    fi
fi

# The client and server binaries are the process boundary most groups use.
# The harness resolves them itself, by name, from the CANDIDATE_* variables
# below -- the names are the step's own interface section's, and the harness
# applies them name-major over the directories it searches. The driver does
# not pre-resolve a binary and does not prefer any spelling of its own: a
# second resolution rule written here could only ever disagree with that one.
target_dir=${CARGO_TARGET_DIR:-$workspace_root/target}

export QUICHE_CRATE_DIR="$crate_dir"
export QUICHE_WORKSPACE="$workspace_root"
export QUICHE_ASSETS="$assets"
export QUICHE_LOGDIR="$log_dir"

# What `verifier::testkit` reads. The harness has to find the candidate's
# binaries, and in this image they are not under /app/target: CARGO_TARGET_DIR
# is set image-wide so the prewarmed dependency graph is reused, which moves
# every artefact to /opt/cargo-target. Telling the harness where the tree and
# the artefacts actually are keeps that an image detail instead of something
# each of the fifteen steps' test files has to know.
export CANDIDATE_ROOT="$workspace_root"
export CANDIDATE_TARGET_DIR="$target_dir"
# Scratch directories are deliberately never cleaned up: when a case fails, the
# document root, the captured stdout and the server log it left behind are the
# evidence. Rooting them in the log directory keeps them beside the case log.
export VERIFIER_SCRATCH="$log_dir/scratch"
mkdir -p "$VERIFIER_SCRATCH"

# ---------------------------------------------------------------------------
# 4. The throw-away harness crate.
#
# It lives outside /app so that a candidate cannot make its own acceptance pass
# by editing the cases, and so that nothing the harness needs is ever added to
# the candidate's manifest. It declares exactly one dependency — a path
# dependency on the candidate's own transport crate — so a harness build
# failure is always about the candidate's public surface and never about a
# registry.
# ---------------------------------------------------------------------------
# Does the candidate's manifest declare a Cargo feature by this name?
#
# Either an explicit entry under [features], or an optional dependency of the
# same name, which Cargo turns into a feature implicitly.
# Does the candidate's manifest declare `$2` as a feature?
#
# Three spellings are legal Cargo for "this crate can be built with a `qlog`
# feature", and all three have to be recognised or a correct manifest is read
# as not declaring it, the feature is dropped from the harness's own edge, and
# every `cap` group fails to link for a reason that is not the candidate's:
#
#   [features]
#   qlog = []
#
#   [dependencies]
#   qlog = { version = "..", optional = true }
#
#   [dependencies.qlog]
#   optional = true
#
# The third puts the name in the section header and never in field 1, which is
# why the spelling is tracked as well as the key.
declares_feature() {
    awk -v want="$2" '
        /^[[:space:]]*\[/ {
            sec = $1
            gsub(/^\[|\]$/, "", sec)
            section = sec
            dep_table = (sec == "dependencies." want || sec == "dev-dependencies." want \
                         || sec == "build-dependencies." want)
            next
        }
        $1 == want && $2 == "=" && section == "features" { found = 1 }
        $1 == want && $2 == "=" && section ~ /dependencies$/ \
            && $0 ~ /optional[ \t]*=[ \t]*true/ { found = 1 }
        dep_table && $1 == "optional" && $2 == "=" && $3 == "true" { found = 1 }
        END { exit found ? 0 : 1 }
    ' "$1"
}

prepare_harness() {
    rm -rf -- "$harness"
    mkdir -p "$(dirname "$harness")"
    # The whole tree, not a hand-listed subset: the harness is a two-member
    # workspace (the verifier crate and `support/`, the independent QUIC
    # implementation) and it carries its own `assets/` — the TLS keypair and
    # the RFC vectors the cases load through `testkit::asset`. Copying file
    # patterns instead would silently drop whichever of those a future step
    # starts using, and the resulting build failure would be charged to the
    # candidate.
    cp -a -- "$assets/harness" "$harness"
    # The only edit: the candidate's crate path, which is not known until the
    # probe above has run. Resolved here rather than in the checked-in manifest
    # so the manifest stays identical in all fifteen steps.
    sed -i "s#@@CRATE_DIR@@#$crate_dir#g" "$harness/Cargo.toml"
    # Optional feature requests, resolved against the candidate's own manifest.
    #
    # Cargo validates every feature reference while it resolves the graph,
    # before it compiles anything, so asking a milestone for a feature it does
    # not declare fails the whole harness build -- including the gate targets,
    # which never touch the feature. Names marked `# optional-feature:` in the
    # harness manifest are therefore kept only when the candidate declares
    # them. The scored case that needs one then fails to compile by itself,
    # which is the right answer for a candidate that has not built it.
    for feat in $(sed -n 's/^#[[:space:]]*optional-feature:[[:space:]]*//p' \
        "$harness/Cargo.toml"); do
        if declares_feature "$crate_dir/Cargo.toml" "$feat"; then
            printf 'kept optional feature %s\n' "$feat" \
                >>"$log_dir/harness-features.log"
        else
            sed -i "s/\"$feat\"[[:space:]]*,[[:space:]]*//; s/,[[:space:]]*\"$feat\"//; s/\"$feat\"//" \
                "$harness/Cargo.toml"
            printf 'dropped optional feature %s: the candidate does not declare it\n' \
                "$feat" >>"$log_dir/harness-features.log"
        fi
    done
    # No lockfile, on purpose. One authored against the reference tree would
    # pin the candidate's own dependency versions, turning a legitimate
    # difference in their manifest into a harness build failure that reads as
    # their fault. The registry cache is prewarmed, so resolving offline here
    # costs nothing.
    rm -f -- "$harness/Cargo.lock"
}

harness_build=0
if [ "$candidate_build" -eq 1 ]; then
    prepare_harness
    (cd "$harness" && timeout "$HARNESS_BUILD_TIMEOUT" \
        cargo test --offline --no-run -j 4) \
        >"$log_dir/harness-build.log" 2>&1 && harness_build=1
fi

# The case pool starts here, so a slow build cannot eat it.
case_deadline=$(( $(date +%s) + CASE_BUDGET_TOTAL ))
budget_exhausted=0

# remaining_budget -> seconds left in the shared pool, or 0
remaining_budget() {
    local r=$(( case_deadline - $(date +%s) ))
    [ "$r" -lt 0 ] && r=0
    printf '%s\n' "$r"
}

# run_case <log-name> <test-target> <test-fn>
#
# Each case is bounded by the smaller of PER_CASE_MAX and what is left of
# CASE_BUDGET_TOTAL, so the cases can never overrun that total however many of
# them hang. A killed case exits non-zero and scores that one group 0, which is
# the same outcome as any other failure; once the pool is spent the remaining
# groups are failed without running and the reason is recorded, which is still a
# zero rather than a lost run.
run_case() {
    local name="$1" target="$2" fn="$3" remaining limit status
    remaining=$(remaining_budget)
    if [ "$remaining" -le 5 ]; then
        budget_exhausted=1
        printf 'the aggregate case budget of %s s was exhausted before this case ran\n' \
            "$CASE_BUDGET_TOTAL" >"$log_dir/$name.log"
        return 1
    fi
    if [ ! -d "$harness" ]; then
        # The harness crate is assembled only after a candidate transport crate
        # has been located. When it was not, every case here would fail on `cd`
        # with a shell error in its log, which reads as a broken driver rather
        # than as a result. The group does fail -- but for a definite reason,
        # and the reason belongs on the group that fired it.
        {
            printf 'the harness crate was never assembled, so this case could not run.\n'
            printf 'assembly is skipped when no candidate transport crate was located\n'
            printf '(crate_dir=%s): there was nothing for the harness to link against.\n' "$crate_dir"
            printf 'This group fails for that reason, not for anything it asserts.\n'
        } >"$log_dir/$name.log"
        return 1
    fi
    limit=$PER_CASE_MAX
    [ "$remaining" -lt "$limit" ] && limit=$remaining
    (cd "$harness" && timeout "$limit" \
        cargo test --offline --test "$target" "$fn" -- --exact --nocapture) \
        >"$log_dir/$name.log" 2>&1
    status=$?
    [ "$status" -eq 0 ] || return "$status"
    # Every invocation asserts an exact executed count: a name filter that
    # matches nothing still exits 0, and would otherwise be scored as a pass.
    grep -q 'test result: ok\. 1 passed; 0 failed; 0 ignored' "$log_dir/$name.log"
}

# ---------------------------------------------------------------------------
# 5. The gate.
#
# Proof of life plus inherited regression: that the candidate builds, that its
# two binaries still complete a handshake and a transfer over real UDP, and
# that one deterministic end-to-end path per earlier milestone still works.
#
# Gate groups earn nothing. They only veto: if any one of them fails the step
# is worth zero however much of this step's own capability landed. That is
# deliberate. A candidate that implements this release by breaking the last one
# has not advanced the ladder, and an additive score would pay it for the parts
# that still happen to work.
#
# The corollary governs what is allowed in here. A gate case that can fail for
# a reason other than the candidate's code -- a wall clock, a host's CPU count,
# an unordered iteration read as ordered -- is not weak coverage, it is a step
# that randomly scores zero for everyone including the reference. Every case
# below is deterministic, and the ones that were not were deleted rather than
# demoted; NOTES.md lists them and why.
#
# Behaviour this step deliberately changes is likewise not in here. A migration
# left in the gate is a step whose own reference implementation fails it.
# ---------------------------------------------------------------------------
gate_ok=1
gate_log=$log_dir/gate.txt
: > "$gate_log"

gate_check() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$gate_log"
    else
        printf 'FAIL %s\n' "$name" >> "$gate_log"
        gate_ok=0
    fi
}

candidate_builds() { [ "$candidate_build" -eq 1 ]; }

# Every other gate group is a case or a driver and leaves `$log_dir/<name>.log`
# behind, which is where the scorer reads the reason a veto fired. This one is
# a flag set back in section 3, so give it the log the flag came from.
if [ -f "$log_dir/candidate-build.log" ]; then
    cp -f "$log_dir/candidate-build.log" "$log_dir/candidate-workspace-builds.log"
else
    # Section 3 runs cargo only when a quiche crate was located. When it was
    # not, no candidate-build.log exists, and copying it silently left this
    # group with no log at all -- which the scorer reports as "the case did not
    # run". That reads like a harness that failed to fire, when in fact the
    # group failed for a definite reason. A veto must carry its reason on the
    # group that fired it, so write it here rather than leave the scorer to
    # guess. The step-level build_note says the same thing; this puts it where
    # a reader looks first.
    {
        printf 'no cargo build was attempted: crate_dir=%s\n' "$crate_dir"
        printf 'no Cargo.toml declaring the package name `quiche` was found at\n'
        printf '/app or /app/quiche, so there was no transport crate to build.\n'
        printf 'This group fails by definition: proof-of-life cannot pass when\n'
        printf 'the candidate shipped no library to prove alive.\n'
    } > "$log_dir/candidate-workspace-builds.log"
fi
gate_check candidate-workspace-builds candidate_builds
# T3: Carried because this step moves the Huffman coder out of the crate that owns the QPACK implementation. A request and a response are exchanged over an in-memory HTTP/3 pair and every field arrives intact, indexed and literal alike, **in order**. The request is the four pseudo-headers, all of them QPACK static table entries. The response mixes one static entry, `:status: 200`, with two literal fields, one of which carries a non-ASCII value. The literals are the point. A static-table entry is an index on the wire and never reaches the Huffman coder; a literal does, because the encoder writes the shorter of the raw and coded forms and the decoder has to invert whichever it finds. This step took that coder out of the transport crate and put it in `octets` behind a non-default feature, so the failure this group exists to catch is a candidate that relocates the code correctly and forgets to turn the feature on for the transport crate: the build succeeds, the static-table fields still arrive, and every literal comes back wrong or not at all. Order is asserted as well as content. QPACK may choose its representation per field but may not reorder a header section, and a decoder that emitted the indexed fields first and the literals afterwards would satisfy a set comparison while breaking every HTTP/3 client. It is a gate group, so it only vetoes, and it is deliberately weaker than the scored Huffman group: it asserts that header coding still works end to end, not that any particular byte was produced.
gate_check reg-01-h3-static-table run_case reg-01-h3-static-table reg reg_01_h3_static_table
# T2: Carried as this step's re-check of a packet-protection observation taken off the wire. The verifier takes the connection's generation-0 traffic secrets from its keylog, derives the next generation itself, and injects a 1-RTT packet sealed with the new keys and the key-phase bit set. It proves the secrets before using them by opening one of the candidate's own packets with the generation-0 set, so a key-schedule disagreement between verifier and candidate cannot read as a candidate fault. Four assertions follow: 1. the candidate decrypts the injected packet -- so it derived the same next-generation keys; 2. the header-protection key was not rotated. This is implied rather than separately asserted: the verifier applied generation-0 header protection, so a candidate that rotated it could not find the packet number and nothing after this point would succeed; 3. a second update before the first is acknowledged is `Err(Error::KeyUpdate)`; 4. the candidate's own next short-header packet has the phase bit set. Carried because it is the one inherited group here that reaches the wire. The other two end at the HTTP/3 API, and a candidate can satisfy both while producing short-header packets the peer cannot open. This step rewrites the lost-frame handler, which decides what goes into a retransmitted packet and therefore runs inside the same send path that seals every 1-RTT packet; a key schedule or key-phase bookkeeping disturbed there breaks this group and nothing else in the file. It is also the cheapest orthogonality available: everything else inherited is header coding, because header coding is what moved. It reads no clock and waits for no timer. Everything it observes is a property of bytes that were produced.
gate_check reg-09-key-update run_case reg-09-key-update reg reg_09_key_update
# T1: The end-to-end HTTP/3 fetch, run between the candidate's own `quiche-server` and its own `quiche-client`, as two real processes over UDP loopback. The server is started on a loopback port serving a 64 KiB file the verifier wrote. The client fetches it with `--no-verify` and with `--http-version HTTP/3` pinned rather than left to the apps' own negotiation, exits 0 within the group's deadline, and the bytes on its stdout match the file byte-for-byte. Pinning the version is what keeps the inherited observation HTTP/3 and stops it quietly becoming a different group. This is the plan-mandated end-to-end regression, and it is carried at every step for the same reason: it is the one observation that requires the whole stack -- the workspace, the transport crate, the HTTP/3 layer, QPACK, the examples and the two binaries -- to be simultaneously correct. This step adds two workspace members and moves a piece of QPACK's machinery into a different crate, either of which can produce a package that compiles and does not work. The case takes the harness's T1 serial guard, so it does not contend with the other process-spawning groups for ports.
gate_check reg-01-h3-get run_case reg-01-h3-get reg reg_01_h3_get
# T1: Proof of life, and nothing else. The candidate's own `quiche-server` is started on a loopback port with `--listen`, `--cert`, `--key`, `--root` and `--no-retry`; its own `quiche-client` fetches one file from it with `--no-verify`; the client exits 0 and the bytes it wrote match the file the server was serving, byte-for-byte. Every other option is the reference's own default. Nothing from this step's milestone appears here on purpose -- no netlog, no Huffman coder, no `accept_with_retry`, no PMTU accessor. Those are scored where they can be seen. This group is the floor underneath all of them, and it is the group that fails first if the workspace's growth from nine members to eleven broke the build of the two binaries that were already there, or if moving the Huffman coder into `octets` left the transport crate unable to build at all. `--no-retry` is not incidental here. This step's scored Retry group drives the exchange itself through the public API; the proof-of-life path deliberately does not, so that a candidate whose Retry handling is wrong fails the group that prices it rather than the one that vetoes everything. It earns nothing. Under `reward = gate x score` it can only veto.
gate_check gate-endtoend run_case gate-endtoend gate gate_endtoend

# ---------------------------------------------------------------------------
# 6. The scored groups.
#
# This step's new capability, plus peripheral breadth. Each group is one
# coherent behaviour and is invoked separately, so a failure localises, and
# every group runs even after another has failed: a partial implementation
# keeps exactly the credit it earned.
#
# Weights live in `/tests/groups.json` and sum to one across the groups here,
# so this step's score is in [0, 1] and is the weighted fraction of its own new
# behaviour that works. Nothing in this section knows a weight -- it records
# PASS or FAIL per group and the scorer prices it -- so a revision that edits a
# group here cannot silently desync the driver from the manifest.
# ---------------------------------------------------------------------------
group_log=$log_dir/groups.txt
: > "$group_log"

score_if() {
    local name="$1"; shift
    if "$@"; then
        printf 'PASS %s\n' "$name" >> "$group_log"
    else
        printf 'FAIL %s\n' "$name" >> "$group_log"
    fi
}

# T4: The Huffman coder at its new address, reached from outside the workspace, and checked against the code the specification fixes. The verifier writes a small crate into scratch -- a `Cargo.toml` with its own empty `[workspace]` table so it is not pulled into the candidate's, and a path dependency on `<candidate root>/octets` with `features = ["huffman_hpack"]` -- and a `main.rs` that prints one line per observation. Building that crate is the first assertion, and it is the one that makes this a T4 group rather than a source inspection: an `octets` that has no such feature, or that has the feature but not the three entry points, does not compile against it, and nothing has been read from the candidate's source to find that out. It is built with `cargo build --offline -j 4` and with `CARGO_TARGET_DIR` pointed at the target directory the driver already used for the candidate's workspace, so the dependency is already compiled and the probe build is a link. The probe's output is compared against a fixed table, line for line, in order. A mismatch is reported as the first differing line with both sides quoted, so a failure names the input that was coded wrongly rather than saying the output differed. ``` enc|www.example.com|false|f1e3c2e5f23a6ba0ab90f4ff len|www.example.com|false|12 enc|no-cache|false|a8eb10649cbf len|no-cache|false|6 enc|custom-key|false|25a849e95ba97d7f len|custom-key|false|8 enc|custom-value|false|25a849e95bb8e8b4bf len|custom-value|false|9 enc|/index.html|false|60d5485f2bce9a68 len|/index.html|false|8 enc|a|false|1f len|a|false|1 enc||false| len||false|0 enc|WWW.EXAMPLE.COM|false|e5cb92f83f21d1af3e05ef6ad1 len|WWW.EXAMPLE.COM|false|13 enc|WWW.EXAMPLE.COM|true|f1e3c2e5f23a6ba0ab90f4ff len|WWW.EXAMPLE.COM|true|12 dec|f1e3c2e5f23a6ba0ab90f4ff|www.example.com dec|a8eb10649cbf|no-cache dec|25a849e95ba97d7f|custom-key dec|25a849e95bb8e8b4bf|custom-value dec|60d5485f2bce9a68|/index.html dec|| roundtrip|www.example.com|false|www.example.com roundtrip|WWW.EXAMPLE.COM|false|WWW.EXAMPLE.COM roundtrip|WWW.EXAMPLE.COM|true|www.example.com len_unprofitable|00|err len_unprofitable|00010203|err short_buffer|err ``` `enc` is `put_huffman_encoded::<LOWER_CASE>` into a fresh buffer, rendered as hex. `len` is `huffman_encoding_len::<LOWER_CASE>` on the same input, and every `len` line is the byte length of the `enc` line above it -- that pairing is the point of listing both. `dec` is `get_huffman_decoded` over the bytes. The three `roundtrip` lines encode and then decode, and the third is the one that shows `LOWER_CASE` is applied before coding rather than after: the value that comes back is lower case, so the transformation happened on the way in. The last three lines are the negatives. `len_unprofitable` asks for the encoded length of input whose encoding would not be shorter, and gets an error both for a single zero byte and for four ascending bytes. `short_buffer` asks the encoder to write `www.example.com` into a four-byte buffer and gets an error rather than a truncated write. Each is an exact-answer negative: the assertion is that the call failed, not that it failed with a particular message. The values are the canonical HPACK examples and are fixed by the code table. They were re-derived against the reference implementation before being written here.
score_if cap-huffman-in-octets run_case cap-huffman-in-octets cap cap_huffman_in_octets
# T4: The netlog reader against a fixture the verifier writes, parsed into an exact expectation table. The fixture is a complete twelve-event netlog in the shape Chromium writes them: a constants line ending in a bare comma, an `"events": [` line, ten event lines ending in commas, and a final event line that closes the array and the document. It records one HTTP/3 session -- session begin, transport parameters sent, request headers, a priority update, a packet sent, a stream frame received, response headers decoded, data sent, settings sent, an unrelated socket event, session end, and a STOP_SENDING sent. **The event type numbers in the fixture are not Chromium's.** They are 500 to 504 for the QUIC types, 600 to 604 for the HTTP/3 types and 700 for the socket type, and the phase map gives `PHASE_NONE`, `PHASE_BEGIN` and `PHASE_END` the values 0, 1 and 2. Nothing outside this file uses those numbers. A reader that resolved names from a built-in table instead of from the file's own `logEventTypes` and `logEventPhase` maps produces a different answer for every line, which is precisely the property being scored: the constants are the file's, and the crate exists to read them. The probe crate -- again outside the workspace, again a path dependency, this time on `<candidate root>/netlog` plus `serde_json` -- reads the constants, skips the array-opening line, and then for each record prints ``` <index>|<type>|<phase>|<time>|<source id>|<source type>|<parsed event> ``` where the type and phase are the strings `populate_strings` resolved, the time is `time_num` after the caller parsed the decimal string, and the last field is a stable rendering of what `parse_event` returned. The rendering is written by the probe, not by the crate: it names the variant and the handful of fields the case cares about, so that the expectation does not depend on anyone's `Debug` output. ``` constants version=1 tick_offset=1700000000000 types=11 phases=3 0|QUIC_SESSION|PHASE_BEGIN|12|41|25|quic:session host=quic.test port=443 cid=5f6e7d8c 1|QUIC_SESSION_TRANSPORT_PARAMETERS_SENT|PHASE_NONE|13|41|25|quic:tp-sent initial_source_connection_id 5f6e7d8c 2|HTTP3_HEADERS_SENT|PHASE_NONE|21|41|25|h3:headers-sent id=0 headers=[:method: GET/:scheme: https/:authority: quic.test/:path: /index.html] 3|HTTP3_PRIORITY_UPDATE_SENT|PHASE_NONE|22|41|25|h3:priority-update elem=0 field=u=3, i ty=request_stream 4|QUIC_SESSION_PACKET_SENT|PHASE_NONE|23|41|25|quic:packet-sent level=ENCRYPTION_FORWARD_SECURE pn=7 sent_us=1234567 5|QUIC_SESSION_STREAM_FRAME_RECEIVED|PHASE_NONE|34|41|25|quic:stream-recv id=0 fin=false off=0 len=1450 6|HTTP3_HEADERS_DECODED|PHASE_NONE|35|41|25|h3:headers-decoded id=0 headers=[:status: 200/content-type: text/plain] 7|HTTP3_DATA_SENT|PHASE_NONE|41|41|25|h3:data-sent id=0 len=4096 8|HTTP3_SETTINGS_SENT|PHASE_NONE|42|41|25|none 9|SOCKET_ALIVE|PHASE_NONE|43|9|8|none 10|QUIC_SESSION|PHASE_END|44|41|25|none 11|QUIC_SESSION_STOP_SENDING_FRAME_SENT|PHASE_NONE|51|41|25|quic:stop-sending id=0 err=3 records=12 ``` Four lines carry most of the weight. Lines 0 and 10 are the *same* event type in two phases, and only one of them parses into a session event -- the reader distinguishes them by phase, not by type. Line 8 is a type the crate recognises by name and does not model, and line 9 is a type outside every family prefix; both must be `None` rather than an error, and a reader that treats an unmodelled event as a failure stops at line 8. Line 11 is the last record in the file, the one whose trailing `]}` the record reader has to strip, and it is the line that would be lost by an off-by-one at end of input -- which is why the count is printed and asserted rather than left implicit. The comparison is line for line against the table above, with the first difference reported. The whole fixture is the verifier's own bytes, so there is nothing timing-dependent, network-dependent or clock-dependent in it.
score_if cap-netlog run_case cap-netlog cap cap_netlog
# T3: A full Retry exchange driven through the public API, in memory, three times: once correctly and twice with one of the two connection IDs wrong. Each leg builds a client with `quiche::connect` and takes its first Initial without a server on the other side. The verifier parses that packet with `Header::from_slice`, and plays the server itself: it picks a Retry source connection ID that is deliberately **not** the connection's eventual SCID, calls `quiche::retry` with the client's SCID, the Initial's destination CID, that new SCID, a twenty-byte token and the packet's version, and hands the Retry back to the client. The client's response is the first observation. It produces a second Initial that carries a non-empty token and whose destination connection ID is the Retry source CID -- not the one it started with. Both are asserted. The server side is then built with `quiche::accept_with_retry`, given a fresh connection SCID and a `RetryConnectionIds` whose two fields the leg controls, and the two ends are pumped against each other for up to thirty-two rounds. | leg | `original_destination_cid` | `retry_source_cid` | expected | |---|---|---|---| | positive | the first Initial's DCID | the Retry's SCID | both ends established, client `local_error` is `None` | | negative A | the first Initial's DCID | a bogus CID | client not established, `local_error` is `(is_app = false, 0x08)` | | negative B | a bogus CID | the Retry's SCID | client not established, `local_error` is `(is_app = false, 0x08)` | The two negatives are what make the positive mean something. A server implementation that ignored `retry_cids` entirely and echoed its own SCID -- which is what `accept` does -- would pass a positive-only version of this group whenever the test happened to choose matching IDs, and the whole point of the new entry point is that they need not match. Here they deliberately do not: the connection's SCID and the Retry's SCID are different values in every leg, so a server that conflates them fails the positive leg too. `0x08` is `TRANSPORT_PARAMETER_ERROR`, and it is required by RFC 9000 Section 7.3 rather than chosen by this crate. The assertion is on the error code and on the `is_app` flag being false; nothing reads a reason string. **In memory, and on purpose.** This is a T3 group rather than a T1 one because the shipped `quiche-server` does not use this entry point -- it calls `quiche::accept` -- so there is no command line that would exercise it. The public API is the only surface it is reachable from.
score_if cap-accept-with-retry run_case cap-accept-with-retry cap cap_accept_with_retry
# T2: That a lost STOP_SENDING comes back when the peer may still send, and does not when the peer has finished -- decrypted off the wire, both ways. Each leg runs a handshaked pair and then: 1. the peer opens a stream and sends data on it, with or without a fin depending on the leg; 2. this endpoint calls `stream_shutdown` with `Shutdown::Read` and an application error code, which queues a STOP_SENDING; 3. the datagram carrying it is taken and **withheld** -- never delivered; 4. six further rounds of ordinary traffic are exchanged on a second stream, so the peer acknowledges packets numbered after the withheld one; 5. every datagram this endpoint sent is decrypted with 1-RTT keys taken from the connection's own keylog, and its frames are decoded. Loss is established by the packet reordering threshold of RFC 9002 Section 6.1 -- later packets acknowledged, the withheld one not -- and not by waiting for a timer. Both legs assert that at least one packet was declared lost, so a leg that failed to create the loss it was arranging fails loudly instead of quietly reporting "no retransmission". | leg | the peer's stream when STOP_SENDING is sent | expected | |---|---|---| | A | still open, no fin sent | the frame appears again in a later packet | | B | already finished, fin delivered | it does not appear again | The frame is matched exactly -- the STOP_SENDING variant with this stream id and this application error code -- not by counting frames or by searching for a type byte. The stream id and the error code are this group's own choices, held in `const`s inside the case and deliberately not named here: what is asserted is that the code handed to `stream_shutdown` in step 2 is the code that comes back on the wire, and a contract that pinned a number would let an implementation emit *that* number instead of carrying the caller's. The packets are the real ones: they are read out of the send path, decrypted with the traffic secret from the keylog, and parsed into frames, so nothing here depends on an internal counter or a log line. Leg B is the half that a plausible wrong implementation fails. Retransmitting unconditionally satisfies "the frame comes back" and violates Section 13.3's condition, which stops the retransmission once the receiving part of the stream has reached "Data Recvd". Both legs were measured against the previous step's tree as well: there, neither leg retransmits, because that tree has no arm for this frame in its lost-frame handler at all.
score_if cap-retransmit-stop-sending run_case cap-retransmit-stop-sending cap cap_retransmit_stop_sending
# T2: That a lost MAX_STREAMS_BIDI comes back -- decrypted off the wire, like its STOP_SENDING sibling. The case runs a handshaked pair and then: 1. completes client-initiated bidirectional streams, one at a time, until a datagram the **server** sends is found to carry a MAX_STREAMS frame for bidirectional streams. The loop is bounded and fails loudly if no grant ever appears, so a candidate that never regrants stream credit fails here rather than skipping the part that matters; 2. **withholds** that datagram -- it is never delivered -- and delivers the rest of the same batch; 3. exchanges six further rounds of ordinary traffic, so the client acknowledges packets numbered after the withheld one; 4. decrypts every datagram the server sent afterwards with 1-RTT keys taken from the connection's own keylog, and decodes their frames. Loss is established by the packet reordering threshold of RFC 9002 Section 6.1 -- later packets acknowledged, the withheld one not -- and not by waiting for a timer. The case asserts that the server declared at least one packet lost, so a run that failed to create the loss it was arranging fails loudly instead of quietly reporting "no retransmission". The keys are the **server's**, read from the client's keylog, because the server is the endpoint granting credit here. The frame is matched on its variant and its bidirectional flag, not by counting frames or searching for a type byte. One property of the arrangement carries the whole leg, and it is deliberate: **the filler traffic in step 3 runs on a unidirectional stream.** Completing more bidirectional streams would give the server a fresh reason to send MAX_STREAMS, and the leg would then pass against an implementation whose lost-frame handler does nothing at all. With the filler on a unidirectional stream, retransmission is the only route by which a second bidirectional grant can appear. Measured against the previous step's tree as well: there the frame never comes back, because that tree has no arm for it in its lost-frame handler.
score_if cap-retransmit-max-streams run_case cap-retransmit-max-streams cap cap_retransmit_max_streams
# T3: `stream_discard` as the receive-side sibling of `stream_recv`, in four exact legs on an in-memory pair. The client sends 4000 bytes on stream 0 with a fin. The server then discards in two pieces and asks twice more: | call | returns | |---|---| | `stream_discard(0, 1000)` | `Ok((1000, false))` | | `stream_discard(0, 3000)` | `Ok((3000, true))` | | `stream_discard(0, 1000)` | `Err(Error::Done)` | | `stream_discard(400, 1000)` | `Err(Error::InvalidStreamState(400))` | and `stream_finished(0)` is true between the second call and the third. Every leg is an exact value rather than a bound. The first shows the `len` argument is a ceiling that is honoured when more is available; the second shows `fin` arriving on the call that consumes the last byte and not before; the third shows an exhausted stream reporting `Done` rather than a zero-length success, which is the difference between a discard loop that terminates and one that spins; the fourth shows an unknown stream id being refused, with that id echoed back in the error. The pair runs a plain ALPN, not HTTP/3, so the only stream in play is the one the case opened and nothing else is competing for the connection's flow control window. The whole group is a single in-process exchange with no timers.
score_if cap-stream-discard run_case cap-stream-discard cap cap_stream_discard
# T3: `pmtu()` and `revalidate_pmtu()` as a state machine with four observable states, on an in-memory pair. | when | `pmtu()` | |---|---| | before the handshake, discovery on | `None` | | after handshake and settle, discovery **off** | `None` | | after handshake and settle, discovery **on** | `Some(v)`, the same `v` at both ends | | immediately after `revalidate_pmtu()` | `None` again | | after a further settle | `Some(v)` again | and the discovered value satisfies `1200 <= v <= 1452` -- the QUIC minimum datagram size from RFC 9000 Section 14, and the maximum this harness's pair will send. The second row is what stops this group from being satisfied by a stub. An accessor hard-wired to return a plausible number passes the third row and fails the second; one hard-wired to return `None` passes rows one, two and four and fails the third. The two together require the value to actually track whether discovery ran. The fourth and fifth rows are `revalidate_pmtu`. The `None` immediately after the call is checked before anything else is sent, which is the only moment at which it is unambiguous: it shows the call restarted the search rather than merely scheduling a probe for later. The value that comes back afterwards is compared to the one from before, so a revalidation on an unchanged path settles where it settled the first time. The bound is one-sided at neither end by accident: an exact figure would be an assertion about this harness's datagram size rather than about the candidate, and a bound that only checked the floor would accept an implementation that reported a number larger than anything it could send.
score_if cap-pmtu-discovered run_case cap-pmtu-discovered cap cap_pmtu_discovered
# T4: The workspace layout, read the way cargo reads it. Two halves. First, each of the eleven expected members has a manifest at `<candidate root>/<name>/Cargo.toml` -- the nine carried forward and the two new ones, `netlog` and `qlog-dancer`. Second, ``` cargo metadata --offline --no-deps --format-version 1 ``` is run at the candidate root and its `packages` array is checked: every expected package name is present as a package whose id is a local path, and the number of local-path package ids is exactly eleven. Counting by path id rather than by matching names is deliberate. `qlog` is a substring of `qlog-dancer`, so a substring search over the metadata finds the first inside the second and would report a package that is not there; and a name-only check would not notice a twelfth member that should not exist. `--no-deps` is what makes the count a statement about the workspace rather than about the dependency graph, and `--offline` is what makes it run in the verifier at all. **This is a layout group and is scored as one.** It is weight 1 -- structural breadth, not the milestone. It asserts nothing about behaviour, and the OBSERVATION-TOOLBOX's one exception to the no-source-reading rule is exactly this: a manifest may be read as a description of the package's shape, never as evidence of what the code does.
score_if cap-eleven-member-workspace run_case cap-eleven-member-workspace cap cap_eleven_member_workspace
# T3: The contraction of `CongestionControlAlgorithm`, read as the integer each name resolves to rather than as the presence of a Rust identifier. This release deletes the `BBR` and `BBR2` variants and points both of their names at the gcongestion implementation. `FromStr` still accepts five names, and three of them now answer the same number: | name | discriminant | |---|---| | `reno` | 0 | | `cubic` | 1 | | `bbr` | 4 | | `bbr2` | 4 | | `bbr2_gcongestion` | 4 | and `"BBR"`, `"bbr3"` and `""` are refused with `Error::CongestionControl`. The enum is `#[repr(C)]` and the C API hands these values across the boundary unchanged, so the name-to-integer mapping is the part of this change a caller outside Rust can see. The previous milestone answered 2 for `bbr` and 3 for `bbr2`; a candidate that keeps those variants is selecting a controller this release no longer has, and every C caller that names either string gets it. Compared as integers, through `from_str`, and never by naming a variant. A case that wrote `CongestionControlAlgorithm::BBR` would fail to compile here rather than fail an assertion, which would cost a candidate every group in the file instead of this one. The whole group is three lines of table lookup with no connection, no timers and no I/O.
score_if cap-cc-name-collapse run_case cap-cc-name-collapse cap cap_cc_name_collapse

# ---------------------------------------------------------------------------
# 7. Report.
#
#     reward = gate x score
#
# `score.py` does the arithmetic against the manifest, because the two checks
# that matter are both about groups going missing -- a declared group with no
# recorded result, or a recorded result for a group nobody priced -- and both
# are easier to get right over parsed JSON than over shell word splitting. It
# prints the reward and writes reward_details.json, naming the gate group that
# vetoed the step and quoting what it saw.
#
# If it cannot run at all, that is a verifier defect and not a capability
# result, and the crash path in section 0 says so in those words.
# ---------------------------------------------------------------------------
score_input=$(printf '{"step_num":%d,"tag":"%s","log_dir":"%s","manifest":"/tests/groups.json","crate_dir":"%s","candidate_build":%s,"harness_build":%s,"fixture_ok":%s,"budget_exhausted":%s}\n' \
    "$step_num" "$step_tag" "$log_dir" "$crate_dir" \
    "$([ "$candidate_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$harness_build" -eq 1 ] && echo true || echo false)" \
    "$([ "$fixture_ok" -eq 1 ] && echo true || echo false)" \
    "$([ "$budget_exhausted" -eq 1 ] && echo true || echo false)")

reward=$(printf '%s' "$score_input" | python3 /tests/score.py 2>"$log_dir/score.err")
score_status=$?

case "$reward" in
    0|0.*|1|1.0*) ;;
    *) reward='' ;;
esac

if [ "$score_status" -ne 0 ] || [ -z "$reward" ]; then
    fail_everything "the verifier could not score this step: score.py exited $score_status saying '$(tr -d '\n"\\' < "$log_dir/score.err" | tail -c 300)'. Nothing was measured, so this is an unattributable verifier failure rather than a capability result"
    reported=1
    exit 0
fi

reported=1
report "$reward"
exit 0
